    function copyTextSafe(txt, btn, okMsg) {
      const done = (ok) => {
        if (!btn) return;
        const orig = btn.getAttribute('data-orig-lbl') || btn.textContent;
        btn.setAttribute('data-orig-lbl', orig);
        btn.textContent = ok ? (okMsg || 'Copied ✓') : 'Select & Copy Manually';
        setTimeout(() => { btn.textContent = orig; }, 2000);
      };
      if (navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
        navigator.clipboard.writeText(String(txt)).then(() => done(true)).catch(() => {
          try {
            const ta = document.createElement('textarea');
            ta.value = String(txt);
            ta.style.position = 'fixed';
            ta.style.opacity = '0';
            document.body.appendChild(ta);
            ta.select();
            const ok = document.execCommand('copy');
            document.body.removeChild(ta);
            done(Boolean(ok));
          } catch (e) { done(false); }
        });
      } else {
        try {
          const ta = document.createElement('textarea');
          ta.value = String(txt);
          ta.style.position = 'fixed';
          ta.style.opacity = '0';
          document.body.appendChild(ta);
          ta.select();
          const ok = document.execCommand('copy');
          document.body.removeChild(ta);
          done(Boolean(ok));
        } catch (e) { done(false); }
      }
    }
