    let _hzLastT = 0, _hzPeak = 0, _hzSamples = [];
    function sampleMouseHz(ev) {
      const now = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
      if (_hzLastT > 0) {
        const dt = now - _hzLastT;
        if (dt > 0.08 && dt < 50) {
          const instHz = Math.round(1000 / dt);
          _hzSamples.push(instHz);
          if (_hzSamples.length > 24) _hzSamples.shift();
          const avgHz = Math.round(_hzSamples.reduce((a, b) => a + b, 0) / _hzSamples.length);
          if (avgHz > _hzPeak) _hzPeak = avgHz;
          const elLive = document.getElementById('hzLiveVal');
          const elPeak = document.getElementById('hzPeakVal');
          const elMs = document.getElementById('hzMsVal');
          if (elLive) elLive.textContent = avgHz + ' Hz';
          if (elPeak) elPeak.textContent = _hzPeak + ' Hz';
          if (elMs) elMs.textContent = (1000 / Math.max(1, avgHz)).toFixed(2) + ' ms';
        }
      }
      _hzLastT = now;
    }
    function resetMouseHz() {
      _hzLastT = 0; _hzPeak = 0; _hzSamples = [];
      const elLive = document.getElementById('hzLiveVal');
      const elPeak = document.getElementById('hzPeakVal');
      const elMs = document.getElementById('hzMsVal');
      if (elLive) elLive.textContent = 'Move Mouse...';
      if (elPeak) elPeak.textContent = '0 Hz';
      if (elMs) elMs.textContent = '0.00 ms';
    }
    let _flickState = { active: false, hits: 0, misses: 0, times: [], lastSpawn: 0 };
    function _spawnNextFlickDot() {
      const dot = document.getElementById('flickTargetDot');
      if (!dot) return;
      const spots = [[18,28],[78,62],[34,70],[68,24],[50,48],[24,54],[82,32],[42,26]];
      const pick = spots[(_flickState.hits + _flickState.misses) % spots.length];
      const jx = Math.max(10, Math.min(88, pick[0] + Math.round((Math.random() - 0.5) * 14)));
      const jy = Math.max(18, Math.min(78, pick[1] + Math.round((Math.random() - 0.5) * 16)));
      dot.style.left = jx + '%';
      dot.style.top = jy + '%';
      dot.style.display = 'block';
      _flickState.lastSpawn = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
    }
    function startFlickDrill() {
      _flickState = { active: true, hits: 0, misses: 0, times: [], lastSpawn: 0 };
      const stEl = document.getElementById('flickStatsBar');
      const btn = document.getElementById('flickStartBtn');
      if (btn) btn.textContent = '🎯 Drill Active (1/5)...';
      if (stEl) stEl.textContent = 'Click the neon target reticle as fast and accurately as possible (Target 1 of 5)...';
      _spawnNextFlickDot();
    }
    function hitFlickTarget(ev) {
      if (ev && ev.stopPropagation) ev.stopPropagation();
      if (!_flickState.active) return;
      const now = (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
      const dt = Math.max(80, Math.round(now - _flickState.lastSpawn));
      _flickState.times.push(dt);
      _flickState.hits++;
      const stEl = document.getElementById('flickStatsBar');
      const btn = document.getElementById('flickStartBtn');
      if (_flickState.hits >= 5) {
        _flickState.active = false;
        const dot = document.getElementById('flickTargetDot');
        if (dot) dot.style.display = 'none';
        const avg = Math.round(_flickState.times.reduce((a, b) => a + b, 0) / _flickState.times.length);
        const shots = _flickState.hits + _flickState.misses;
        const acc = Math.round((_flickState.hits / Math.max(1, shots)) * 100);
        const tier = avg <= 240 ? 'Tier-1 Pro Reflex' : avg <= 330 ? 'Competitive Ranked' : 'Controlled Anchor';
        const advice = _flickState.misses >= 2
          ? 'Overshoot detected (' + _flickState.misses + ' misclicks) — consider lowering sensitivity by 6%–10% for tighter micro-correction.'
          : 'Zero-overshoot micro-flick control verified at current sensitivity.';
        if (stEl) stEl.textContent = 'Drill Complete: Avg Flick TTD ' + avg + ' ms (' + tier + ') • Accuracy ' + acc + '% (' + _flickState.hits + '/' + shots + ') • ' + advice;
        if (btn) btn.textContent = '↻ Replay 5-Target Flick Drill';
      } else {
        if (btn) btn.textContent = '🎯 Drill Active (' + (_flickState.hits + 1) + '/5)...';
        if (stEl) stEl.textContent = 'Hit ' + _flickState.hits + '/5 (' + dt + ' ms) • Misses: ' + _flickState.misses + ' — Acquire next target!';
        _spawnNextFlickDot();
      }
    }
    function missFlickTarget(ev) {
      if (!_flickState.active) return;
      _flickState.misses++;
