      if (stEl) stEl.textContent = 'Off-target misclick (' + _flickState.misses + ' misses) — Steady crosshair and click the neon target!';
    }
    let _cadenceTimer = null, _cadenceAudioCtx = null, _cadenceSpm = 176, _cadenceStepToggle = false;
    function _playCadenceTick() {
      const beacon = document.getElementById('cadenceBeacon');
      const stepLbl = document.getElementById('cadenceFootLbl');
      _cadenceStepToggle = !_cadenceStepToggle;
      if (beacon) {
        beacon.style.transform = 'scale(1.28)';
        beacon.style.background = _cadenceStepToggle ? '#EA580C' : '#10B981';
        setTimeout(() => { if (beacon) beacon.style.transform = 'scale(1.0)'; }, 90);
      }
      if (stepLbl) stepLbl.textContent = _cadenceStepToggle ? 'LEFT FOOTSTRIKE ●' : 'RIGHT FOOTSTRIKE ●';
      try {
        const Ctx = window.AudioContext || window.webkitAudioContext;
        if (!Ctx) return;
        if (!_cadenceAudioCtx) _cadenceAudioCtx = new Ctx();
        if (_cadenceAudioCtx.state === 'suspended') _cadenceAudioCtx.resume();
        const osc = _cadenceAudioCtx.createOscillator();
        const gain = _cadenceAudioCtx.createGain();
        osc.type = 'sine';
        osc.frequency.value = _cadenceStepToggle ? 880 : 660;
        gain.gain.setValueAtTime(0.12, _cadenceAudioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, _cadenceAudioCtx.currentTime + 0.035);
        osc.connect(gain);
        gain.connect(_cadenceAudioCtx.destination);
        osc.start();
        osc.stop(_cadenceAudioCtx.currentTime + 0.04);
      } catch (e) {}
    }
    function setCadenceSpm(spmVal) {
